import sys

def is_subsequence_brute(s, t):
    i = 0
    for ch in s:
        j = t.find(ch, i)
        if j == -1:
            return False
        i = j + 1
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_subsequence_brute(data[0], data[1]) else 'false')

