import sys
from bisect import bisect_left

def is_subsequence_best(s, t):
    # 预处理 t：每个字符的位置列表
    pos = {ch: [] for ch in 'abcdefghijklmnopqrstuvwxyz'}
    for i, ch in enumerate(t):
        pos[ch].append(i)
    cur = -1
    for ch in s:
        if not pos[ch]:
            return False
        idx = bisect_left(pos[ch], cur + 1)
        if idx == len(pos[ch]):
            return False
        cur = pos[ch][idx]
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_subsequence_best(data[0], data[1]) else 'false')
